<?php $types=['sales'=>'Ventes','stock'=>'Stock complet','low_stock'=>'Stock faible','expiry'=>'Expirations','customers'=>'Clients','orders'=>'Commandes','purchases'=>'Approvisionnements','returns'=>'Retours','inventories'=>'Inventaires','loyalty'=>'Fidélité'];?><div class="d-flex justify-content-between align-items-end mb-3"><div><h2 class="fw-bold">Rapports KIN-MART</h2><div class="text-muted">États opérationnels, financiers et commerciaux exportables.</div></div><div class="d-flex gap-2"><a class="btn btn-outline-dark" href="<?=e(base_url('reports/csv?type='.urlencode($type).'&from='.$from.'&to='.$to))?>">CSV</a><a class="btn btn-outline-success" href="<?=e(base_url('reports/xls?type='.urlencode($type).'&from='.$from.'&to='.$to))?>">Excel</a><a class="btn btn-outline-danger" href="<?=e(base_url('reports/pdf?type='.urlencode($type).'&from='.$from.'&to='.$to))?>">PDF</a></div></div><div class="km-card p-3 mb-3"><form class="row g-2"><div class="col-md-4"><label class="form-label">Rapport</label><select class="form-select" name="type"><?php foreach($types as $k=>$v):?><option value="<?=e($k)?>" <?=selected($type,$k)?>><?=e($v)?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Du</label><input type="date" class="form-control" name="from" value="<?=e($from)?>"></div><div class="col-md-3"><label class="form-label">Au</label><input type="date" class="form-control" name="to" value="<?=e($to)?>"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-km w-100">Afficher</button></div></form></div><?php if($type==='sales'&&!empty($summary)):?><div class="row g-3 mb-3"><div class="col-md-4"><div class="km-card km-stat"><div class="label">Chiffre d'affaires</div><div class="value"><?=money($summary['ca'])?></div></div></div><div class="col-md-4"><div class="km-card km-stat"><div class="label">Coût des marchandises</div><div class="value"><?=money($summary['cost'])?></div></div></div><div class="col-md-4"><div class="